package io.github.jesterportfolio.hearth.economy;

import java.util.*;import java.util.concurrent.*;import java.sql.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.survival.housing.HousingSettings;

/** 기존 native realm을 유지하는 추가 정책/월드/개인 위치 저장. 발급 context·realm lock·CAS 공통. */
public final class RpgStore {
    public record Extra(String role,String key,UUID world,long seed){}
    public record Pvp(UUID house,boolean enabled,long revision){}
    public record Home(UUID player,UUID world,double x,double y,double z,float yaw,float pitch,long revision){public Home{Objects.requireNonNull(player);Objects.requireNonNull(world);if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)||!Float.isFinite(yaw)||!Float.isFinite(pitch)||Math.abs(x)>29999000||Math.abs(z)>29999000||y< -2032||y>2032||revision<0)throw new IllegalArgumentException("RPG_HOME");}}
    public enum Mode {PRIVATE,PUBLIC,LIST,REMOVED}
    public record Acl(UUID id,UUID owner,UUID world,int x,int y,int z,int x2,int y2,int z2,Mode mode,Set<UUID> allowed,long revision){public Acl{Objects.requireNonNull(id);Objects.requireNonNull(owner);Objects.requireNonNull(world);Objects.requireNonNull(mode);allowed=Set.copyOf(allowed);if(Math.abs((long)x)>29999000||Math.abs((long)x2)>29999000||Math.abs((long)z)>29999000||Math.abs((long)z2)>29999000||y< -2032||y2>2032||x2<x||y2<y||z2<z||(long)x2-x>1||(long)y2-y>1||(long)z2-z>1||allowed.size()>64||revision<0)throw new IllegalArgumentException("RPG_ACL");}public boolean permits(UUID player){return owner.equals(player)||mode==Mode.PUBLIC||mode==Mode.LIST&&allowed.contains(player);}public boolean contains(UUID w,int bx,int by,int bz){return world.equals(w)&&bx>=x&&bx<=x2&&by>=y&&by<=y2&&bz>=z&&bz<=z2;}}
    public record Snapshot(List<Extra> extras,Map<UUID,Pvp> pvp,Map<UUID,Home> homes,List<Acl> objects){public Snapshot{extras=List.copyOf(extras);pvp=Map.copyOf(pvp);homes=Map.copyOf(homes);objects=List.copyOf(objects);}}
    private final PostgresProgressStore db;private final EconomyStore economy;private final UUID realm,publicWorld;private final int sx,sy,sz;private final HousingSettings geometry;
    public RpgStore(PostgresProgressStore db,EconomyStore economy,UUID realm,UUID publicWorld,int sx,int sy,int sz,HousingSettings geometry){this.db=db;this.economy=economy;this.realm=realm;this.publicWorld=publicWorld;this.sx=sx;this.sy=sy;this.sz=sz;this.geometry=geometry;}
    private static StorageFailure fail(String code){return new StorageFailure("rpg",code);}
    @FunctionalInterface private interface Work<T>{T run(Connection c)throws Exception;}
    private <T>CompletionStage<T> tx(ServerProgressAccess.Context ctx,Work<T> work){return db.module("rpg",c->{c.setAutoCommit(false);try{if(!realm.equals(ctx.storyRunId()))throw fail("RPG_REALM");economy.housingLock(c,ctx);T value=work.run(c);c.commit();return value;}catch(Exception error){c.rollback();throw error;}finally{c.setAutoCommit(true);}});}
    private ServerProgressAccess.Context system(){return economy.context(realm,new UUID(0,0));}
    private PreparedStatement st(Connection c,String sql,Object...args)throws SQLException{var s=c.prepareStatement(sql);for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;}
    private void one(Connection c,String sql,Object...args)throws SQLException{try(var s=st(c,sql,args)){if(s.executeUpdate()!=1)throw fail("RPG_CAS");}}
    public CompletionStage<Void> requireNoState(){return snapshot().thenAccept(s->{if(!s.extras().isEmpty()||!s.pvp().isEmpty()||!s.homes().isEmpty()||!s.objects().isEmpty())throw fail("RPG_RUNTIME_REQUIRED");});}
    public CompletionStage<Snapshot> snapshot(){return tx(system(),c->{var extras=new ArrayList<Extra>();var pvp=new HashMap<UUID,Pvp>();var homes=new HashMap<UUID,Home>();var objects=new ArrayList<Acl>();
        try(var s=st(c,"SELECT * FROM hearth_economy.extra_world WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next())extras.add(new Extra(r.getString("role"),r.getString("world_key"),r.getObject("world_uuid",UUID.class),r.getLong("seed")));}
        try(var s=st(c,"SELECT * FROM hearth_economy.house_pvp WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next()){var row=new Pvp(r.getObject("house_id",UUID.class),r.getBoolean("enabled"),r.getLong("revision"));pvp.put(row.house(),row);}}
        try(var s=st(c,"SELECT * FROM hearth_economy.player_home WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next()){if(homes.size()>=100000)throw fail("RPG_ROW_LIMIT");var row=new Home(r.getObject("player_uuid",UUID.class),r.getObject("world_uuid",UUID.class),r.getDouble("x"),r.getDouble("y"),r.getDouble("z"),r.getFloat("yaw"),r.getFloat("pitch"),r.getLong("revision"));homes.put(row.player(),row);}}
        try(var s=st(c,"SELECT * FROM hearth_economy.object_acl WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next()){if(objects.size()>=100000)throw fail("RPG_ROW_LIMIT");var ids=new HashSet<UUID>();for(Object id:(Object[])r.getArray("allowed").getArray())ids.add(UUID.fromString(id.toString()));objects.add(new Acl(r.getObject("id",UUID.class),r.getObject("owner_uuid",UUID.class),r.getObject("world_uuid",UUID.class),r.getInt("x"),r.getInt("y"),r.getInt("z"),r.getInt("x2"),r.getInt("y2"),r.getInt("z2"),Mode.valueOf(r.getString("mode")),ids,r.getLong("revision")));}}
        return new Snapshot(extras,pvp,homes,objects);
    });}
    public CompletionStage<Void> bindExtra(Extra e){if(!Set.of("novice","end").contains(e.role())||!e.key().matches("hearth_survival:[a-z0-9_]+"))return CompletableFuture.failedFuture(fail("RPG_EXTRA_ROLE"));return tx(system(),c->{try(var s=st(c,"SELECT * FROM hearth_economy.extra_world WHERE realm_id=? AND role=?",realm,e.role());var r=s.executeQuery()){if(r.next()){if(!r.getString("world_key").equals(e.key())||!r.getObject("world_uuid",UUID.class).equals(e.world())||r.getLong("seed")!=e.seed())throw fail("RPG_EXTRA_IDENTITY");return null;}}one(c,"INSERT INTO hearth_economy.extra_world VALUES(?,?,?,?,?)",realm,e.role(),e.key(),e.world(),e.seed());return null;});}
    private void ownedHouse(Connection c,ServerProgressAccess.Context ctx,UUID house)throws Exception{try(var s=st(c,"SELECT owner_id,phase FROM hearth_economy.house WHERE realm_id=? AND house_id=?",realm,house);var r=s.executeQuery()){if(!r.next()||!ctx.playerId().equals(r.getObject(1,UUID.class))||!r.getString(2).equals("ACTIVE"))throw fail("RPG_NOT_OWNER");}}
    public CompletionStage<Void> pvp(ServerProgressAccess.Context ctx,UUID house,boolean value,long revision){return tx(ctx,c->{ownedHouse(c,ctx,house);if(revision<0)one(c,"INSERT INTO hearth_economy.house_pvp VALUES(?,?,?,0) ON CONFLICT DO NOTHING",realm,house,value);else one(c,"UPDATE hearth_economy.house_pvp SET enabled=?,revision=revision+1 WHERE realm_id=? AND house_id=? AND revision=?",value,realm,house,revision);return null;});}
    public CompletionStage<Void> home(ServerProgressAccess.Context ctx,Home row,long revision){if(!ctx.playerId().equals(row.player()))return CompletableFuture.failedFuture(fail("RPG_HOME_OWNER"));return tx(ctx,c->{if(revision<0)one(c,"INSERT INTO hearth_economy.player_home VALUES(?,?,?,?,?,?,?,?,0) ON CONFLICT DO NOTHING",realm,row.player(),row.world(),row.x(),row.y(),row.z(),row.yaw(),row.pitch());else one(c,"UPDATE hearth_economy.player_home SET world_uuid=?,x=?,y=?,z=?,yaw=?,pitch=?,revision=revision+1 WHERE realm_id=? AND player_uuid=? AND revision=?",row.world(),row.x(),row.y(),row.z(),row.yaw(),row.pitch(),realm,row.player(),revision);return null;});}
    private void objectOwner(Connection c,ServerProgressAccess.Context ctx,Acl a)throws Exception{
        if(!a.owner().equals(ctx.playerId()))throw fail("RPG_NOT_OWNER");
        if(a.world().equals(publicWorld)){String plot;try(var s=st(c,"SELECT plot_id FROM hearth_economy.housing_plot WHERE realm_id=? AND player_id=?",realm,ctx.playerId());var r=s.executeQuery()){if(!r.next())throw fail("RPG_NOT_OWNER");plot=r.getString(1);}var box=geometry.plots().stream().filter(p->p.id().equals(plot)).findFirst().orElseThrow();if(a.x()<sx+box.x()||a.x2()>=sx+box.x()+box.width()||a.z()<sz+box.z()||a.z2()>=sz+box.z()+box.width()||a.y()<sy||a.y2()>=sy+box.height())throw fail("RPG_OBJECT_BOUNDS");}
        else{try(var s=st(c,"SELECT house_id,width FROM hearth_economy.house WHERE realm_id=? AND owner_id=? AND world_uuid=? AND phase='ACTIVE'",realm,ctx.playerId(),a.world());var r=s.executeQuery()){if(!r.next())throw fail("RPG_NOT_OWNER");int half=r.getInt("width")/2;if(a.x()< -half||a.x2()>=half||a.z()< -half||a.z2()>=half)throw fail("RPG_OBJECT_BOUNDS");}}
    }
    public CompletionStage<Void> object(ServerProgressAccess.Context ctx,Acl row,long revision){return tx(ctx,c->{objectOwner(c,ctx,row);var allowed=c.createArrayOf("uuid",row.allowed().toArray());if(revision<0)one(c,"INSERT INTO hearth_economy.object_acl VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0) ON CONFLICT DO NOTHING",realm,row.id(),row.owner(),row.world(),row.x(),row.y(),row.z(),row.x2(),row.y2(),row.z2(),row.mode().name(),allowed);else one(c,"UPDATE hearth_economy.object_acl SET mode=?,allowed=?,x2=?,y2=?,z2=?,revision=revision+1 WHERE realm_id=? AND id=? AND owner_uuid=? AND revision=? AND world_uuid=? AND x=? AND y=? AND z=?",row.mode().name(),allowed,row.x2(),row.y2(),row.z2(),realm,row.id(),ctx.playerId(),revision,row.world(),row.x(),row.y(),row.z());return null;});}
    public CompletionStage<Void> reserveSkill(ServerProgressAccess.Context ctx,String id,long now,long until){if(!id.matches("hearth/[a-z0-9_]+")||until<=now||until-now>3_600_000)return CompletableFuture.failedFuture(fail("RPG_COOLDOWN"));return tx(ctx,c->{one(c,"INSERT INTO hearth_economy.skill_cooldown VALUES(?,?,?,?) ON CONFLICT(realm_id,player_uuid,skill_id) DO UPDATE SET until_millis=EXCLUDED.until_millis WHERE hearth_economy.skill_cooldown.until_millis<=?",realm,ctx.playerId(),id,until,now);return null;});}
    public CompletionStage<Map<String,Long>> cooldowns(ServerProgressAccess.Context ctx){return tx(ctx,c->{var result=new HashMap<String,Long>();try(var s=st(c,"SELECT skill_id,until_millis FROM hearth_economy.skill_cooldown WHERE realm_id=? AND player_uuid=?",realm,ctx.playerId());var r=s.executeQuery()){while(r.next())result.put(r.getString(1),r.getLong(2));}return Map.copyOf(result);});}
    public CompletionStage<Void> removeObject(ServerProgressAccess.Context ctx,Acl row){return tx(ctx,c->{objectOwner(c,ctx,row);one(c,"UPDATE hearth_economy.object_acl SET mode='REMOVED',allowed=ARRAY[]::uuid[],revision=revision+1 WHERE realm_id=? AND id=? AND owner_uuid=? AND revision=?",realm,row.id(),ctx.playerId(),row.revision());return null;});}
}
